for(const l of LESSONS){
 const original=JOURNEY_DATA.base[l.id];
 if(CODE_LESSONS[l.id]){
  const tasks=CODE_LESSONS[l.id];
  const guided=tasks.map((t,i)=>({...t,starter:JOURNEY_DATA.scaffolds[l.id][i],prompt:'Complete o código de apoio. '+t.prompt}));
  l.qs=[...original.qs,...guided.map(t=>({q:t.prompt,h:t.hint,why:'Você completou o trecho e verificou o resultado.',o:[],a:0})),...tasks.map(t=>({q:t.prompt,h:t.hint,why:'Você construiu e verificou seu código.',o:[],a:0}))];
  STEPS[l.id]=[...original.steps,...guided.map(t=>({kind:'code',intro:t.intro,code:t})),...tasks.map(t=>({kind:'code',intro:t.intro,code:t}))];
 }else{
  l.qs=[...original.qs,...(JOURNEY_DATA.extra[l.id]||[]).map(e=>e.q)];
  STEPS[l.id]=[...original.steps,...(JOURNEY_DATA.extra[l.id]||[]).map(e=>e.step)];
 }
}
for(const l of LESSONS)l.qs.forEach((q,i)=>{
 const step=STEPS[l.id][i];if(step.kind==='code'||step.answer||q.o.length<2)return;
 const options=[...q.o],answer=q.a,shift=([...l.id].reduce((n,c)=>n+c.charCodeAt(0),0)+i*7)%options.length;
 const order=options.map((_,j)=>(j+shift)%options.length);q.o=order.map(j=>options[j]);q.a=order.indexOf(answer);
 if(step.errors){const old=step.errors;step.errors=Object.fromEntries(order.map((j,k)=>[k,old[j]]));}
});
